"""Buscador de activos: catálogo completo de Capital.com, búsqueda en vivo, categorías correctas y respuesta más rápida de los botones

Ejecutar desde la raíz del proyecto:   python instalar_buscador_capital.py
Idempotente, sin .bak. Cada archivo debe estar en alguna de las versiones conocidas (la actual de Cristian, o la de
una etapa intermedia del trabajo de Emilio); si alguno tiene cambios distintos, NO se instala nada y se indica cuál.
"""
import base64, hashlib, io, json, os, sys, zipfile

# Hashes de los estados de partida aceptados por archivo (None = el archivo no existía) y archivos que se eliminan.
ACEPTADAS = json.loads("{\"aplicacion_principal/precarga.py\": [\"41f85a3473a15919df123e0677c7d6a6a5693bf5ed50dc2d6130bd44b6aefa06\"], \"componentes_plataforma/buscador/datos.py\": [\"abca10bd5ac8519bd47d18a842f6f32a2437ec994a7e9d58bfdc251697193a78\"], \"componentes_plataforma/buscador/dialogo.py\": [\"f1c84a52ca70f08ab99f154dcbeef8e6fdf0fef177121c3950678962e4a2372c\"], \"componentes_plataforma/conectar_cuenta/pantalla.py\": [\"e3d2cbc6d473fc99c9ef96d6da15903f74e053dafeb4769c8b49e0583cdd71af\"], \"componentes_plataforma/favoritos/estado.py\": [\"f38e40e3f7b25174f4d18059551033fd3c8b6a09063b33e995bacf2f53e11add\"], \"componentes_plataforma/lista_activos/acciones.py\": [\"25c78114ee5a49a0a8b125d40861d1f72936eece178e8ffdd3b7b6c851f5d2ff\"], \"herramientas/gestor_lista_activos.py\": [\"7b4524f94f3bb0d2f53e48164ee9735fd98df2f38008d02b25e4f0a11e6a95a8\"], \"proveedores/capital_mt5_compat.py\": [\"027bcdab817a2151b0d9e3eea92fbe69b5fa55e7ec5a40b4f03c16df6315bfa2\"]}")
ARCHIVOS = ["aplicacion_principal/precarga.py", "componentes_plataforma/buscador/datos.py", "componentes_plataforma/buscador/dialogo.py", "componentes_plataforma/conectar_cuenta/pantalla.py", "componentes_plataforma/favoritos/estado.py", "componentes_plataforma/lista_activos/acciones.py", "herramientas/gestor_lista_activos.py", "proveedores/capital_mt5_compat.py"]
BORRAR = []
ZIP_B64 = ""


def norm(b):
    return b.replace(b"\r\n", b"\n")


def sha(f):
    """Hash del archivo (sin distinguir saltos de línea de Windows) o None si no existe."""
    return hashlib.sha256(norm(open(f, "rb").read())).hexdigest() if os.path.exists(f) else None


def main():
    z = zipfile.ZipFile(io.BytesIO(base64.b64decode(ZIP_B64)))
    nuevos = {f: norm(z.read(f)) for f in ARCHIVOS}
    destino = {f: hashlib.sha256(nuevos[f]).hexdigest() for f in ARCHIVOS}
    pendientes = [f for f in ARCHIVOS if sha(f) != destino[f]]
    a_borrar = [f for f in BORRAR if os.path.exists(f)]
    if not pendientes and not a_borrar:
        print("Ya estaba instalado: no hay nada que hacer.")
        return
    problemas = [f + (" ya existe con otro contenido" if sha(f) else " falta") + " o difiere de las versiones conocidas (¿cambios sin subir?)"
                 for f in pendientes if sha(f) not in ACEPTADAS[f]]
    if problemas:
        print("No se instaló nada:")
        for p in problemas:
            print("  -", p)
        sys.exit(1)
    for f in pendientes:
        datos = nuevos[f]
        os.makedirs(os.path.dirname(f) or ".", exist_ok=True)
        if os.path.exists(f) and b"\r\n" in open(f, "rb").read():
            datos = datos.replace(b"\n", b"\r\n")
        with open(f, "wb") as fh:
            fh.write(datos)
    for f in a_borrar:
        os.remove(f)
    print("Listo: %d archivos actualizados, %d eliminados." % (len(pendientes), len(a_borrar)))


if __name__ == "__main__":
    main()
